// Content plan — proven channel-funnel mix (research 2025):
//   authority 40-50% · engagement 20-30% · proof 15-20% · offers 10-15%
// Cadence: Mon/Wed/Fri 11:00 EET (daytime engagement window).
//   Mon  → authority   ([Build Log] / [Playbook] insight)
//   Wed  → engagement  (reaction-CTA question post)
//   Fri  → ISO-week % 3: 0=offer · 1=authority · 2=proof  (~11% offers)
// Offers follow company policy ONLY — free 30-min audit, Polar plans,
// the automation-checklist lead magnet. No invented discounts.
const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const now = new Date();
const dow = (now.getDay() + 6) % 7; // 0=Mon
const isoWeek = (() => {
  const d = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
})();

const OFFERS = [
  {
    key: 'audit',
    prompt: 'Write an offer post for the Cloudless Telegram channel: invite readers to a free 30-minute cloud & automation audit. Explain in one line what they get (a concrete map of what to automate first + honest cost savings estimate). No pressure language, no fake scarcity — it is a real free service.',
    image_prompt: 'minimalist dark tech illustration, a magnifying glass over a cloud infrastructure diagram, cyan and magenta accents, professional, no text',
    buttons: [[{ text: 'Book the free audit', url: 'https://cloudless.gr/contact' }]],
    tag: '[Deal]'
  },
  {
    key: 'plans',
    prompt: 'Write an offer post for the Cloudless Telegram channel: our automation plans are live — self-hosted social automation that runs while you sleep. One line on what a plan includes, honest pricing link, no hype.',
    image_prompt: 'minimalist dark tech illustration, a rocket leaving a cloud platform, cyan and magenta accents, professional, no text',
    buttons: [[{ text: 'See plans & pricing', url: 'https://social.cloudless.gr/pricing' }]],
    tag: '[Deal]'
  },
  {
    key: 'checklist',
    prompt: 'Write an offer post for the Cloudless Telegram channel: give away our 12-Automation Checklist PDF — the exact checklist we use to decide what to automate in a small business. Free download, explain the one insight it gives you.',
    image_prompt: 'minimalist dark tech illustration, a checklist document floating over clouds, cyan and magenta accents, professional, no text',
    buttons: [[{ text: 'Download the checklist', url: 'https://cloudless.gr/automation-checklist.pdf' }]],
    tag: '[Deal]'
  }
];

const PILLARS = {
  authority: {
    prompt: 'Write an authority post for the Cloudless Telegram channel: one practical automation or self-hosting insight for small-business owners, drawn from real cloudless.gr engineering (self-hosted stack, Cloudflare workers, n8n pipelines, local AI inference). Teach ONE thing fully. No invented metrics.',
    image_prompt: 'minimalist dark tech illustration, glowing server racks and automation gears inside a cloud, cyan and magenta accents, professional, no text',
    tag: '[Playbook]',
    buttons: null
  },
  engagement: {
    prompt: 'Write an engagement post for the Cloudless Telegram channel: ask the audience ONE opinion question about their own automation or hosting setup (e.g. what they still do manually that a machine should handle). Two lines of context max, then the question, then a reaction CTA.',
    image_prompt: 'minimalist dark tech illustration, two chat bubbles over a circuit board, cyan and magenta accents, professional, no text',
    tag: '[Question]',
    buttons: null
  },
  proof: {
    prompt: 'Write a proof post for the Cloudless Telegram channel: share ONE real result from the cloudless.gr self-hosted stack — use only verifiable facts (runs on a Raspberry Pi cluster, zero SaaS subscriptions, self-hosted Nextcloud + mail + social automation). Concrete and humble, never invented numbers.',
    image_prompt: 'minimalist dark tech illustration, a small raspberry pi board powering a giant cloud, cyan and magenta accents, professional, no text',
    tag: '[Build Log]',
    buttons: null
  }
};

let pillar, offer = null;
if (body.pillar && (PILLARS[body.pillar] || body.pillar === 'offer')) {
  pillar = body.pillar;
} else if (dow === 0) {
  pillar = 'authority';
} else if (dow === 2) {
  pillar = 'engagement';
} else if (dow === 4) {
  pillar = isoWeek % 3 === 0 ? 'offer' : (isoWeek % 3 === 1 ? 'authority' : 'proof');
} else {
  pillar = 'authority';
}

if (pillar === 'offer') {
  offer = OFFERS[Math.floor(isoWeek / 3) % OFFERS.length];
} else {
  offer = PILLARS[pillar];
}

const prompt = body.topic ? `${offer.prompt} Topic angle: ${body.topic}` : offer.prompt;
return [{ json: {
  pillar,
  series_tag: offer.tag,
  prompt: `${offer.tag} ${prompt}`,
  image_prompt: body.image_prompt || offer.image_prompt,
  buttons: offer.buttons,
  account_id: body.account_id || $env.CLOUDLESS_TELEGRAM_ACCOUNT_ID || 'f75d0132-0964-4236-9766-a6603c997dfd',
  publish: body.publish === false ? false : true
} }];

const crypto = require('crypto');
const secret = ($env.SOCIAL_TOTP_SECRET || '').trim().replace(/\s+/g, '').toUpperCase();
const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
const clean = secret.replace(/=+$/, '');
let bits = 0, value = 0;
const bytes = [];
for (const ch of clean) {
  const idx = ALPHABET.indexOf(ch);
  if (idx === -1) throw new Error('Invalid base32 char in SOCIAL_TOTP_SECRET');
  value = (value << 5) | idx;
  bits += 5;
  if (bits >= 8) { bytes.push((value >>> (bits - 8)) & 0xff); bits -= 8; }
}
const key = Buffer.from(bytes);
const msg = Buffer.alloc(8);
msg.writeBigUInt64BE(BigInt(Math.floor(Date.now() / 30000)));
const digest = crypto.createHmac('sha1', key).update(msg).digest();
const offset = digest[digest.length - 1] & 0x0f;
const otp = ((digest.readUInt32BE(offset) & 0x7fffffff) % 1000000).toString().padStart(6, '0');
return [{ json: { otp } }];

const plan = $('Plan Post (pillar rotation)').item.json;
const copy = $('Generate Copy (DMR)').item.json;
const img = $json;
const caption = (copy.content || '').trim();
return [{ json: {
  caption,
  public_url: img.public_url || null,
  asset_id: img.asset_id || null,
  buttons: plan.buttons,
  account_id: plan.account_id,
  pillar: plan.pillar,
  publish: plan.publish
} }];

